#define LSL (0)
#define LSR (1)
#define RSL (2)
#define RSR (3)
#define RLR (4)
#define LRL (5)

// The three segment types a path can be made up of
#define L_SEG (0)
#define S_SEG (1)
#define R_SEG (2)

#define LSL (0)
#define LSR (1)
#define RSL (2)
#define RSR (3)
#define RLR (4)
#define LRL (5)

typedef struct
{
    double qi[3];       // the initial configuration
    double param[3];    // the lengths of the three segments
    double rho;         // model forward velocity / model angular velocity
    int type;           // path type. one of LSL, LSR, ...
} DubinsPath;

typedef int (*DubinsWord)(double, double, double, double* );
extern DubinsWord dubins_words[];

DubinsWord dubins_words[] = {
    dubins_LSL,
    dubins_LSR,
    dubins_RSL,
    dubins_RSR,
    dubins_RLR,
    dubins_LRL,
};


double fmodr( double x, double y)
{
    return x - y*floor(x/y);
}

double mod2pi( double theta )
{
    return fmodr( theta, 2 * M_PI );
}

int dubins_LSL( double alpha, double beta, double d, double* outputs )
{
    double sa = sin(alpha); 
    double sb = sin(beta); 
    double ca = cos(alpha);
    double cb = cos(beta); 
    double c_ab = cos(alpha - beta);   
    double tmp0 = d+sa-sb;
    double p_squared = 2 + (d*d) -(2*c_ab) + (2*d*(sa - sb));
    if( p_squared < 0 ) {
        return -1;
    }
    double tmp1 = atan2( (cb-ca), tmp0 );
    double t = mod2pi(-alpha + tmp1 );
    double p = sqrt( p_squared );
    double q = mod2pi(beta - tmp1 );
    outputs[0]  = t;                
    outputs[1]  = p;                
    outputs[2]  = q;
    return 0;
}

int dubins_RSR( double alpha, double beta, double d, double* outputs )
{
    double sa = sin(alpha); double sb = sin(beta); 
    double ca = cos(alpha);
    double cb = cos(beta); 
    double c_ab = cos(alpha - beta);   
    double tmp0 = d-sa+sb;
    double p_squared = 2 + (d*d) -(2*c_ab) + (2*d*(sb-sa));
    if( p_squared < 0 ) {
        return -1;
    }
    double tmp1 = atan2( (ca-cb), tmp0 );
    double t = mod2pi( alpha - tmp1 );
    double p = sqrt( p_squared );
    double q = mod2pi( -beta + tmp1 );
    outputs[0]  = t;                
    outputs[1]  = p;                
    outputs[2]  = q;
    return 0;
}

int dubins_LSR( double alpha, double beta, double d, double* outputs )
{
    double sa = sin(alpha); 
    double sb = sin(beta); 
    double ca = cos(alpha);
    double cb = cos(beta); 
    double c_ab = cos(alpha - beta);   
    double p_squared = -2 + (d*d) + (2*c_ab) + (2*d*(sa+sb));
    if( p_squared < 0 ) {
        return -1;
    }
    double p    = sqrt( p_squared );
    double tmp2 = atan2( (-ca-cb), (d+sa+sb) ) - atan2(-2.0, p);
    double t    = mod2pi(-alpha + tmp2);
    double q    = mod2pi( -mod2pi(beta) + tmp2 );
    outputs[0]  = t;                
    outputs[1]  = p;                
    outputs[2]  = q;
    return 0;
}

int dubins_RSL( double alpha, double beta, double d, double* outputs )
{
    double sa = sin(alpha); 
    double sb = sin(beta); 
    double ca = cos(alpha);
    double cb = cos(beta); 
    double c_ab = cos(alpha - beta);   
    double p_squared = (d*d) -2 + (2*c_ab) - (2*d*(sa+sb));
    if( p_squared< 0 ) {
        return -1;
    }
    double p    = sqrt( p_squared );
    double tmp2 = atan2( (ca+cb), (d-sa-sb) ) - atan2(2.0, p);
    double t    = mod2pi(alpha - tmp2);
    double q    = mod2pi(beta - tmp2);
    outputs[0]  = t;                
    outputs[1]  = p;                
    outputs[2]  = q; 
    return 0;
}

int dubins_RLR( double alpha, double beta, double d, double* outputs )
{
    double sa = sin(alpha); 
    double sb = sin(beta); 
    double ca = cos(alpha);
    double cb = cos(beta); 
    double c_ab = cos(alpha - beta);   
    double tmp_rlr = (6. - d*d + 2*c_ab + 2*d*(sa-sb)) / 8.;
    if( fabs(tmp_rlr) > 1) {
        return -1;
    }
    double p = mod2pi( 2*M_PI - acos( tmp_rlr ) );
    double t = mod2pi(alpha - atan2( ca-cb, d-sa+sb ) + mod2pi(p/2.));
    double q = mod2pi(alpha - beta - t + mod2pi(p));
    outputs[0]  = t;                
    outputs[1]  = p;                
    outputs[2]  = q; 
    return 0;
}

int dubins_LRL( double alpha, double beta, double d, double* outputs )
{
    double sa = sin(alpha); 
    double sb = sin(beta); 
    double ca = cos(alpha);
    double cb = cos(beta); 
    double c_ab = cos(alpha - beta);   
    double tmp_lrl = (6. - d*d + 2*c_ab + 2*d*(- sa + sb)) / 8.;
    if( fabs(tmp_lrl) > 1) {
        return -1;
    }
    double p = mod2pi( 2*M_PI - acos( tmp_lrl ) );
    double t = mod2pi(-alpha - atan2( ca-cb, d+sa-sb ) + p/2.);
    double q = mod2pi(mod2pi(beta) - alpha -t + mod2pi(p));
    outputs[0]  = t;                
    outputs[1]  = p;                
    outputs[2]  = q; 
    return 0;
}

int dubins_init_normalised( double alpha, double beta, double d, DubinsPath* path)
{
    double best_cost = INFINITY;
    int    best_word;
    int    i;

    best_word = -1;
    for( i = 0; i < 6; i++ ) {
        double params[3];
        int err = dubins_words[i](alpha, beta, d, params);
        if(err == 0) {
            double cost = params[0] + params[1] + params[2];
            if(cost < best_cost) {
                best_word = i;
                best_cost = cost;
                path->param[0] = params[0];
                path->param[1] = params[1];
                path->param[2] = params[2];
                path->type = i;
            }
        }
    }

    if(best_word == -1) {
        return -1;
    }
    path->type = best_word;
    return 0;
}

int dubins_init( double q0[3], double q1[3], double rho, DubinsPath* path )
{
    int i;
    double dx = q1[0] - q0[0];
    double dy = q1[1] - q0[1];
    double D = sqrt( dx * dx + dy * dy );
    double d = D / rho;
    if( rho <= 0. ) {
        return -1;
    }
    double theta = mod2pi(atan2( dy, dx ));
    double alpha = mod2pi(q0[2] - theta);
    double beta  = mod2pi(q1[2] - theta);
    for( i = 0; i < 3; i ++ ) {
        path->qi[i] = q0[i];
    }
    path->rho = rho;

    return dubins_init_normalised( alpha, beta, d, path );
}

double dubins_path_length( DubinsPath* path )
{
    double length = 0.;
    length += path->param[0];
    length += path->param[1];
    length += path->param[2];
    length = length * path->rho;
    return length;
}

int dubins_path_type( DubinsPath* path ) {
    return path->type;
}

void dubins_segment( double t, double qi[3], double qt[3], int type)
{
    assert( type == L_SEG || type == S_SEG || type == R_SEG );

    if( type == L_SEG ) {
        qt[0] = qi[0] + sin(qi[2]+t) - sin(qi[2]);
        qt[1] = qi[1] - cos(qi[2]+t) + cos(qi[2]);
        qt[2] = qi[2] + t;
    }
    else if( type == R_SEG ) {
        qt[0] = qi[0] - sin(qi[2]-t) + sin(qi[2]);
        qt[1] = qi[1] + cos(qi[2]-t) - cos(qi[2]);
        qt[2] = qi[2] - t;
    }
    else if( type == S_SEG ) {
        qt[0] = qi[0] + cos(qi[2]) * t;
        qt[1] = qi[1] + sin(qi[2]) * t;
        qt[2] = qi[2];
    }
}
/*
    @brief Create a Dubins path between two nodes
    @param costmap: The costmap to use for coordinate conversion
    @param start_node: The starting node of the path
    @param goal_node: The goal node of the path
    @return: A vector of nodes representing the Dubins path from start_node to goal_node
 */
std::vector create_dubins_path(
    nav2_costmap_2d::Costmap2D* costmap,
    const nodeHybrid &start_node, 
    const nodeHybrid &goal_node
) {
    std::vector path_nodes;

    // 1. Convert map coordinates to world coordinates
    double start_x_world, start_y_world;
    double goal_x_world, goal_y_world;
    costmap->mapToWorld(start_node.x, start_node.y, start_x_world, start_y_world);
    costmap->mapToWorld(goal_node.x, goal_node.y, goal_x_world, goal_y_world);

    // Check bounds
    if (start_node.x >= costmap->getSizeInCellsX() || start_node.y >= costmap->getSizeInCellsY() ||
        goal_node.x >= costmap->getSizeInCellsX() || goal_node.y >= costmap->getSizeInCellsY()) {
        RCLCPP_ERROR(rclcpp::get_logger("AstarPlanner"), "Start or goal outside costmap bounds");
        return path_nodes;
    }

    // 2. Create initial and final configurations [x, y, theta]
    double q0[3] = {start_x_world, start_y_world, start_node.yaw};
    double q1[3] = {goal_x_world, goal_y_world, goal_node.yaw};

    // 3. Initialize Dubins path
    double rho = 1.0;  // Adjust if needed
    DubinsPath path;
    if (dubins_init(q0, q1, rho, &path) != 0) {
        RCLCPP_ERROR(rclcpp::get_logger("AstarPlanner"), "Failed to initialize Dubins path");
        return path_nodes;
    }

    // 4. Sample the Dubins path
    double path_length = dubins_path_length(&path);
    double step_size = costmap->getResolution();

    double qi[3] = {q0[0], q0[1], q0[2]};
    double qt[3];

    int segment_types[3];
    switch (path.type) {
        case LSL: segment_types[0] = L_SEG; segment_types[1] = S_SEG; segment_types[2] = L_SEG; break;
        case LSR: segment_types[0] = L_SEG; segment_types[1] = S_SEG; segment_types[2] = R_SEG; break;
        case RSL: segment_types[0] = R_SEG; segment_types[1] = S_SEG; segment_types[2] = L_SEG; break;
        case RSR: segment_types[0] = R_SEG; segment_types[1] = S_SEG; segment_types[2] = R_SEG; break;
        case RLR: segment_types[0] = R_SEG; segment_types[1] = L_SEG; segment_types[2] = R_SEG; break;
        case LRL: segment_types[0] = L_SEG; segment_types[1] = R_SEG; segment_types[2] = L_SEG; break;
        default:
            RCLCPP_ERROR(rclcpp::get_logger("AstarPlanner"), "Invalid Dubins path type");
            return path_nodes;
    }

    // Include start node
    nodeHybrid start;
    start.x = start_node.x;
    start.y = start_node.y;
    start.yaw = start_node.yaw;
    path_nodes.push_back(start);

    for (int seg = 0; seg < 3; seg++) {
        double seg_length = path.param[seg];
        int seg_steps = static_cast(seg_length / step_size) + 1;

        for (int i = 0; i < seg_steps; i++) {
            double t = std::min(step_size * i, seg_length);
            dubins_segment(t, qi, qt, segment_types[seg]);

            unsigned int mx, my;
            if (!costmap->worldToMap(qt[0], qt[1], mx, my)) {
                RCLCPP_WARN(rclcpp::get_logger("AstarPlanner"), "Dubins point (%f, %f) outside costmap", qt[0], qt[1]);
                continue;
            }

            if (costmap->getCost(mx, my) > 0) {
                RCLCPP_WARN(rclcpp::get_logger("AstarPlanner"), "Dubins point (%u, %u) in collision", mx, my);
                continue;
            }

            nodeHybrid node;
            node.x = mx;
            node.y = my;
            node.yaw = mod2pi(qt[2]);
            if (!path_nodes.empty() && node.x == path_nodes.back().x && node.y == path_nodes.back().y) {
                continue;  // Skip duplicates
            }
            path_nodes.push_back(node);

            if (i == seg_steps - 1) {
                qi[0] = qt[0];
                qi[1] = qt[1];
                qi[2] = qt[2];
            }
        }
    }

    // Ensure goal node is included
    if (!path_nodes.empty()) {
        path_nodes.back().x = goal_node.x;
        path_nodes.back().y = goal_node.y;
        path_nodes.back().yaw = goal_node.yaw;
    } else {
        nodeHybrid goal;
        goal.x = goal_node.x;
        goal.y = goal_node.y;
        goal.yaw = goal_node.yaw;
        path_nodes.push_back(goal);
    }

    // Detailed logging
    RCLCPP_INFO(rclcpp::get_logger("AstarPlanner"), "Generated Dubins path with %zu points", path_nodes.size());
    for (size_t i = 0; i < path_nodes.size(); i++) {
        double wx, wy;
        costmap->mapToWorld(path_nodes[i].x, path_nodes[i].y, wx, wy);
        RCLCPP_DEBUG(rclcpp::get_logger("AstarPlanner"), "Point %zu: Map(%u, %u), World(%f, %f), Yaw(%f)", 
                     i, path_nodes[i].x, path_nodes[i].y, wx, wy, path_nodes[i].yaw);
    }

    // Sanity check
    if (path_nodes.size() < 2) {
        RCLCPP_ERROR(rclcpp::get_logger("AstarPlanner"), "Path has fewer than 2 points, controller may reject it");
    }

    return path_nodes;
}


